#include "robotblocks_runtime.h"


static void proceso_1() {
    static RbProcessState s;
    PT_BEGIN(s);
    digitalWrite(LEDG, 1);
    digitalWrite(LEDB, 1);
    digitalWrite(LEDR, 1);
    while (true) {
        digitalWrite(LEDR, 0);
        PT_SLEEP(s, 500);
        digitalWrite(LEDR, 1);
        PT_SLEEP(s, 500);
        PT_YIELD(s);
    }
    PT_END(s);
}

void setup() { Serial.begin(115200); pinMode(LEDG, OUTPUT); pinMode(LEDB, OUTPUT); pinMode(LEDR, OUTPUT); }

void loop() { rb_error_repeat(); proceso_1(); }
